export async function getMetricsForUrls(
  urls: string[],
  options: BulkLookupOptions = {}
): Promise<ReportResponse> {
  const { dateRange, metrics = DEFAULT_METRICS, save = true } = options;

  // Normalize URLs
  const normalizedUrls = normalizeUrls(urls);

if (normalizedUrls.length === 0) {
  return {
    rows: [],
    rowCount: 0,
  };
}

// Build filter
const dimensionFilter = buildUrlFilter(normalizedUrls);

// Get client and property
const client = getClient();
const property = getPropertyId();
const parsedDateRange = parseDateRange(dateRange);

// Build and execute request
const request = {
  property,
  dateRanges: [parsedDateRange],
  dimensions: [{ name: 'pagePath' }, { name: 'pageTitle' }],
  metrics: metrics.map(name => ({ name })),
  dimensionFilter,
};

if (save) {
  const dateStr = typeof dateRange === 'string' ? dateRange : 'custom';
  saveResult(response, 'reports', 'bulk_url_lookup', dateStr);

// Build filename
const timestamp = getTimestamp();
const sanitizedOperation = sanitizeFilename(operation);
const sanitizedExtra = extraInfo ? `__${sanitizeFilename(extraInfo)}` : '';
const filename = `${timestamp}__${sanitizedOperation}${sanitizedExtra}.json`;
const filepath = join(categoryDir, filename);

// Build wrapped result
const result: SavedResult<T> = {
  metadata: {
    savedAt: new Date().toISOString(),
    category,
    operation,
    propertyId: settings.propertyId,
    ...(extraInfo && { extraInfo }),
  },
  data,
};

try {
  const content = readFileSync(filepath, 'utf-8');
  return JSON.parse(content) as SavedResult<T>;
} catch {
  return null;
}
